-- Undo a parking-notes batch: clears each note only while it still holds this batch's text.
begin;
update public.areas set parking_note=null where id='ny_moss_island_climbs' and parking_note='Park in the lot just over the bridge on NY Route 167 in Little Falls: take the first drive on the right after crossing the river and park right under the bridge.';
update public.areas set parking_note=null where id='ut_cat_wall' and parking_note='Park on the east side of the road at the large dirt turn-out at County Road 104 and Utah 211, then go through the ranch gate (close it) and follow a trail northeast, almost 2 miles. A capable 2WD may drive closer; conditions may have changed.';
update public.areas set parking_note=null where id='wv_whippoorwill' and parking_note='Turn onto Whippoorwill Road just off US-19 near the bridge, follow it right and downhill, and park at the pullout on the more obvious second dirt road on the left. If full, park fully off the road; do not use the gravesite parking.';
update public.areas set parking_note=null where id='wv_south_peak_west_face_main_area' and parking_note='Park at the Seneca Rocks visitor center lots (upper or lower; lower is closer) just south on US 33, then hike up Roy Gap Road to the creek crossing with the stone stairs on the far side, which leads up to the West Face.';
update public.areas set parking_note=null where id='wv_reeds_creek' and parking_note='Park at the intersection of Reeds Creek Road with Route 220 near Upper Tract, or in one of two small pull-outs on the left of Reeds Creek Road (about 100 ft and 500 ft in, 2-3 cars each). Parking is limited and can fill; do not park outside the obvious spots.';
update public.areas set parking_note=null where id='nc_laurel_knob' and parking_note='Drive from Cashiers via US 64, Cedar Creek Road and Breedlove Road to the Panthertown Valley trailhead lot at Salt Rock Gap, where the gravel road ends. This trailhead is the only legal access; do not approach from Dillard Canyon (private).';
update public.areas set parking_note=null where id='id_shady_side' and parking_note='The crag is on South 5th Ave in Pocatello, below the Fort Hall Replica and Upper Ross Park. Park at the north or south end of the park; the road is busy, so watch kids and dogs.';
update public.areas set parking_note=null where id='az_overlook_the' and parking_note='The Overlook is on the east side of Highway 89A at the top of Oak Creek Canyon, just before the switchbacks. Use the paved lot, but if staying past 4:30 pm park across the highway because the gates are locked then.';
update public.areas set parking_note=null where id='nl_main_face' and parking_note='Flatrock, about 20 minutes north of St. John''s: park in the East Coast Trail lot just past the public wharf. Parking on Wade''s Lane is no longer permitted, so use the designated lots only.';
update public.areas set parking_note=null where id='al_barn_area' and parking_note='Hospital Boulders: park in the gated lot on the climber-owned property off Scenic Highway in Gadsden, then walk past the barn on the narrow entry road to a trail trending downhill. The property is open dawn to dusk only; the gate combination is shared by the local climbing group.';
update public.areas set parking_note=null where id='al_eddie_area' and parking_note='Hospital Boulders: park in the gated lot on the climber-owned property off Scenic Highway in Gadsden, then walk past the barn and follow the trail downhill and right. The property is open dawn to dusk only; the gate combination is shared by the local climbing group.';
commit;
